{
  "tasks": [
    {
      "task_id": "T01",
      "title": "甲和丙项目的任务数量统计",
      "business_question": "在只看甲和丙的约束下，各项目（甲、丙）的任务数量分别是多少？",
      "priority": "P0",
      "priority_reason": "直接回答核心业务目标“统计甲和丙各项目的任务数量”。删除此任务将无法获取任何关于项目分布的数据，无法支持后续决策。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "field_0002",
                "operator": "in",
                "value": [
                  "甲",
                  "丙"
                ]
              }
            ]
          }
        },
        {
          "step_id": "S02",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              }
            ],
            "dimensions": [
              "field_0002"
            ]
          }
        }
      ]
    }
  ]
}
